{
  "name": "NI CAN总线接口",
  "name_en": "NI CAN Bus Interface",
  "manufacturer": "National Instruments",
  "description": "这是一类由美国国家仪器提供的CAN总线接口硬件，用于将计算机或测试系统连接到CAN网络，实现报文收发、总线监测与通信控制。常用于汽车电子、工业控制和仪器联调中的设备通信、ECU测试与总线数据采集。",
  "description_en": "This is a CAN bus interface device from National Instruments used to connect a computer or test system to a CAN network for message transmission, bus monitoring, and communication control. It is commonly used in automotive electronics, industrial control, and lab test setups for ECU testing, device communication, and CAN data acquisition.",
  "actions": [
    {
      "action_name": "auto-send",
      "description": "发送CAN报文。",
      "description_en": "Send a CAN message."
    },
    {
      "action_name": "auto-reset",
      "description": "复位CAN接口并清除总线错误状态。",
      "description_en": "Reset the CAN interface and clear bus error states."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭CAN接口。",
      "description_en": "Shut down the CAN interface."
    }
  ],
  "tag_hints": [
    "CAN bus communication",
    "National Instruments",
    "automotive ECU testing",
    "industrial fieldbus",
    "message transmission",
    "bus monitoring",
    "data acquisition"
  ]
}

